import{_ as p,a0 as a,w as l,s as r,ao as d,I as i,x as t,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"如何在 winSCP 中使用 sudo | LCTT x X-CMD","titleTemplate":false,"description":"如何在 winSCP 中使用 sudo | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 winSCP 中使用 sudo | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 winSCP 中使用 sudo | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190301 How to use sudo access in winSCP","title":"如何在 winSCP 中使用 sudo","tag":"201903","desc":""},"relativePath":"201903/20190301 How to use sudo access in winSCP.md","filePath":"[post].md"}'),u={name:"201903/20190301 How to use sudo access in winSCP.md"};function w(m,s,C,c,f,k){const e=a("Link");return l(),r("div",null,[s[15]||(s[15]=d(`<h1 id="如何在-winscp-中使用-sudo" tabindex="-1">如何在 winSCP 中使用 sudo <a class="header-anchor" href="#如何在-winscp-中使用-sudo" aria-label="Permalink to “如何在 winSCP 中使用 sudo”">​</a></h1><blockquote><p>用截圖瞭解如何在 winSCP 中使用 sudo。</p></blockquote><p><img src="https://i2.wp.com/kerneltalks.com/wp-content/uploads/2019/03/How-to-use-sudo-access-in-winSCP.png?ssl=1" alt="How to use sudo access in winSCP"></p><p><em>sudo access in winSCP</em></p><p>首先你需要檢查你嘗試使用 winSCP 連接的 sftp 服務器的二進制文件的位置。</p><p>你可以使用以下命令檢查 SFTP 服務器二進制文件位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@kerneltalks ~]# cat /etc/ssh/sshd_config |grep -i sftp-server</span></span>
<span class="line"><span>Subsystem sftp  /usr/libexec/openssh/sftp-server</span></span></code></pre></div><p>你可以看到 sftp 服務器的二進制文件位於 <code>/usr/libexec/openssh/sftp-server</code>。</p><p>打開 winSCP 並單擊“高級”按鈕打開高級設置。</p><p><img src="https://i0.wp.com/kerneltalks.com/wp-content/uploads/2019/03/winscp-advanced-settings.jpg?ssl=1" alt="winSCP advance settings"></p><p><em>winSCP 高級設置</em></p><p>它將打開如下高級設置窗口。在左側面板上選擇“Environment”下的 “SFTP”。你會在右側看到選項。</p><p>現在，使用命令 <code>sudo su -c</code> 在這裏添加 SFTP 服務器值，如下截圖所示：</p><p><img src="https://i1.wp.com/kerneltalks.com/wp-content/uploads/2019/03/SFTP-server-setting-in-winSCP.jpg?ssl=1" alt="SFTP server setting in winSCP"></p><p><em>winSCP 中的 SFTP 服務器設置</em></p><p>所以我們在設置中添加了 <code>sudo su -c /usr/libexec/openssh/sftp-server</code>。單擊“Ok”並像平常一樣連接到服務器。</p><p>連接之後，你將可以從你以前需要 sudo 權限的目錄傳輸文件了。</p><p>完成了！你已經使用 winSCP 使用 sudo 登錄服務器了。</p><hr>`,19)),i("p",null,[s[1]||(s[1]=t("via: ",-1)),n(e,{href:"https://kerneltalks.com/tools/how-to-use-sudo-access-in-winscp/"},{default:o(()=>[...s[0]||(s[0]=[t("https://kerneltalks.com/tools/how-to-use-sudo-access-in-winscp/",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=t("作者：",-1)),n(e,{href:"https://kerneltalks.com"},{default:o(()=>[...s[2]||(s[2]=[t("kerneltalks",-1)])]),_:1}),s[7]||(s[7]=t(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[3]||(s[3]=[t("lujun9972",-1)])]),_:1}),s[8]||(s[8]=t(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:o(()=>[...s[4]||(s[4]=[t("geekpi",-1)])]),_:1}),s[9]||(s[9]=t(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...s[5]||(s[5]=[t("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[10]||(s[10]=[t("LCTT",-1)])]),_:1}),s[13]||(s[13]=t(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:o(()=>[...s[11]||(s[11]=[t("Linux中國",-1)])]),_:1}),s[14]||(s[14]=t(" 榮譽推出",-1))])])}const T=p(u,[["render",w]]);export{g as __pageData,T as default};
